// The 6 Main Phases of the Event Loop:
// 1. Timers (setTimeout)
// 2. Pending Callbacks (system level)
// 3. Idle, Prepare (internal)
// 4. Poll (I/O, fs, http, db! It waits here if nothing else is queued)
// 5. Check (setImmediate)
// 6. Close Callbacks (socket.destroy)

const fs = require('fs');

// This will go to the CHECK phase
setImmediate(() => console.log("Check Phase: setImmediate executed"));

// This goes to the TIMERS phase
setTimeout(() => console.log("Timers Phase: setTimeout executed"), 0);

// This goes to the POLL phase
// fs.readFile(__filename, () => {
//   console.log("Poll Phase: File Read Completed");
// });

console.log("Main Thread: Synchronous code runs before ANY phase begins.");

// Note: Between ANY of these phases, the 'Microtask Queue' is checked!
